-- Schema of a database built by Hibernate ddl-auto=update before Flyway (SCRUM-50):
-- the H2 file committed in git at that point. It has no lecture_notes table.
CREATE SEQUENCE "PUBLIC"."LECTURE_COMMENTS_SEQ" START WITH 1 INCREMENT BY 50;
CREATE CACHED TABLE "PUBLIC"."ASSIGNMENTS"(
    "GRADE" FLOAT(53),
    "ASSIGNMENT_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "LECTURE_ID" BIGINT NOT NULL,
    "STUDENT_ID" BIGINT NOT NULL,
    "SUBMITTED_AT" TIMESTAMP(6) NOT NULL,
    "COMMENT" CHARACTER VARYING(500),
    "STUDENT_COMMENT" CHARACTER VARYING(500),
    "TEACHER_COMMENT" CHARACTER VARYING(500),
    "SUBMISSION_FILE_PATH" CHARACTER VARYING(255) NOT NULL
);
ALTER TABLE "PUBLIC"."ASSIGNMENTS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_E" PRIMARY KEY("ASSIGNMENT_ID");
CREATE CACHED TABLE "PUBLIC"."LECTURE_COMMENTS"(
    "COMMENT_ID" BIGINT NOT NULL,
    "COMMENT" CHARACTER VARYING(1000) NOT NULL,
    "CREATED_AT" TIMESTAMP(6),
    "USER_ID" BIGINT NOT NULL,
    "LECTURE_ID" BIGINT NOT NULL
);
ALTER TABLE "PUBLIC"."LECTURE_COMMENTS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_B" PRIMARY KEY("COMMENT_ID");
CREATE CACHED TABLE "PUBLIC"."ENROLLMENTS"(
    "AVERAGE_GRADE" FLOAT(53),
    "RATING" INTEGER,
    "COURSE_ID" BIGINT NOT NULL,
    "ENROLLED_AT" TIMESTAMP(6) NOT NULL,
    "ENROLLMENT_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "RATED_AT" TIMESTAMP(6),
    "STUDENT_ID" BIGINT NOT NULL,
    "COMPLETION_STATUS" CHARACTER VARYING(30) NOT NULL,
    "REVIEW_TEXT" CHARACTER VARYING(1000)
);
ALTER TABLE "PUBLIC"."ENROLLMENTS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_56" PRIMARY KEY("ENROLLMENT_ID");
CREATE CACHED TABLE "PUBLIC"."LECTURES"(
    "COURSE_ID" BIGINT NOT NULL,
    "LECTURE_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ASSIGNMENT_FILE_PATH" CHARACTER VARYING(50) NOT NULL,
    "TITLE" CHARACTER VARYING(120) NOT NULL,
    "VIDEO_URL" CHARACTER VARYING(500) NOT NULL,
    "DESCRIPTION" CHARACTER VARYING(1000) NOT NULL
);
ALTER TABLE "PUBLIC"."LECTURES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_9" PRIMARY KEY("LECTURE_ID");
CREATE CACHED TABLE "PUBLIC"."COURSES"(
    "COURSE_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "START_DATE" TIMESTAMP(6),
    "TEACHER_ID" BIGINT NOT NULL,
    "STATUS" CHARACTER VARYING(20) NOT NULL,
    "TITLE" CHARACTER VARYING(100) NOT NULL,
    "TOPIC" CHARACTER VARYING(250) NOT NULL,
    "DESCRIPTION" CHARACTER VARYING(1000),
    "PASSING_GRADE" FLOAT(53)
);
ALTER TABLE "PUBLIC"."COURSES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_6" PRIMARY KEY("COURSE_ID");
CREATE CACHED TABLE "PUBLIC"."USERS"(
    "USER_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ROLE" CHARACTER VARYING(20) NOT NULL,
    "STATUS" CHARACTER VARYING(20) NOT NULL,
    "FIRST_NAME" CHARACTER VARYING(50) NOT NULL,
    "LAST_NAME" CHARACTER VARYING(50) NOT NULL,
    "PASSWORD" CHARACTER VARYING(100) NOT NULL,
    "EMAIL" CHARACTER VARYING(254) NOT NULL,
    "PROFILE_PICTURE" CHARACTER VARYING(255),
    "TEACHER_APPROVED" BOOLEAN DEFAULT TRUE NOT NULL
);
ALTER TABLE "PUBLIC"."USERS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4D4" PRIMARY KEY("USER_ID");
ALTER TABLE "PUBLIC"."USERS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4" CHECK("ROLE" IN('TEACHER', 'STUDENT', 'ADMIN')) NOCHECK;
ALTER TABLE "PUBLIC"."ENROLLMENTS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_5" CHECK("COMPLETION_STATUS" IN('IN_PROGRESS', 'COMPLETED', 'DROPPED')) NOCHECK;
ALTER TABLE "PUBLIC"."USERS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4D" UNIQUE("EMAIL");
