ALTER TABLE "PUBLIC"."ENROLLMENTS" ADD CONSTRAINT "PUBLIC"."FK2LHA5VWILCI2YI3VU5AKUSX4A" FOREIGN KEY("STUDENT_ID") REFERENCES "PUBLIC"."USERS"("USER_ID") NOCHECK;
ALTER TABLE "PUBLIC"."ASSIGNMENTS" ADD CONSTRAINT "PUBLIC"."FK5UPCCPVVSVDB194FPRX74Q1CW" FOREIGN KEY("STUDENT_ID") REFERENCES "PUBLIC"."USERS"("USER_ID") NOCHECK;
